import json

def main():
    # Simple Hamiltonian path using the sequential edges 0-1-2-...-11
    path = list(range(12))
    witness = {
        "polarity": "positive",
        "data": {"hamiltonian_path": path}
    }
    print("WITNESS: " + json.dumps(witness))

if __name__ == "__main__":
    main()
